// Land mask (gl-2): Natural Earth 1:110m admin-0 countries (public domain, naturalearthdata.com),
// rasterized to a 0.5° grid (720 × 360, row 0 = 90°N, column 0 = 180°W) and run-length encoded.
// Values: 0 ocean · 1 land · 2 United States · 3 Brazil · 4 China · 5 rest of Latin America · 6 Indonesia, Malaysia, Thailand
// (Singapore is below 1:110m resolution). Generated by a one-off script; the data never changes.
export const W = 720;
export const H = 360;
const RLE = '';
let grid = null;
export function landGrid() {
  if (grid) return grid;
  grid = new Uint8Array(W * H);
  let i = 0;
  const re = /([A-H])([0-9a-z]+)/g;
  let m;
  while ((m = re.exec(RLE))) {
    const v = m[1].charCodeAt(0) - 65;
    const n = parseInt(m[2], 36);
    if (v) grid.fill(v, i, i + n);
    i += n;
  }
  return grid;
}
/** Mask value at latitude/longitude in degrees. */
export function landAt(lat, lon) {
  const g = landGrid();
  const j = Math.min(H - 1, Math.max(0, Math.floor((90 - lat) / 0.5)));
  let i = Math.floor((((lon + 180) % 360) + 360) % 360 / 0.5);
  if (i >= W) i = W - 1;
  return g[j * W + i];
}
